import os
import json
import uuid
import sqlite3
import time
from flask import Flask, request, Response, jsonify, send_from_directory

from openai import OpenAI

app = Flask(__name__, static_folder="static")

REQUESTY_API_KEY = os.environ.get("REQUESTY_API_KEY", "")

client = OpenAI(
    api_key=REQUESTY_API_KEY,
    base_url="",
)

DB_PATH = "chat.db"


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id TEXT NOT NULL,
            role TEXT NOT NULL,
            content TEXT NOT NULL,
            images TEXT,
            ts INTEGER NOT NULL
        )
        """
    )
    conn.commit()
    conn.close()


@app.route("/")
def index():
    return send_from_directory(".", "index.html")


@app.route("/sw.js")
def service_worker():
    return send_from_directory(".", "sw.js", mimetype="application/javascript")


@app.route("/api/chat", methods=["POST"])
def chat():
    data = request.get_json(force=True)
    message = data.get("message", "")
    session_id = data.get("session_id") or str(uuid.uuid4())
    images = data.get("images", [])

    conn = get_db()
    rows = conn.execute(
        "SELECT role, content, images FROM messages WHERE session_id = ? ORDER BY id ASC",
        (session_id,),
    ).fetchall()
    conn.close()

    history = []
    for row in rows:
        role = row["role"]
        content = row["content"]
        row_images = None
        try:
            row_images = json.loads(row["images"]) if row["images"] else None
        except Exception:
            pass
        if role == "user" and row_images:
            parts = [{"type": "text", "text": content}]
            for img in row_images:
                parts.append(
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": "data:"
                            + img.get("media_type", "image/jpeg")
                            + ";base64,"
                            + img.get("data", "")
                        },
                    }
                )
            history.append({"role": role, "content": parts})
        else:
            history.append({"role": role, "content": content})

    if images:
        parts = [{"type": "text", "text": message}]
        for img in images:
            parts.append(
                {
                    "type": "image_url",
                    "image_url": {
                        "url": "data:"
                        + img.get("media_type", "image/jpeg")
                        + ";base64,"
                        + img.get("data", "")
                    },
                }
            )
        user_msg = {"role": "user", "content": parts}
    else:
        user_msg = {"role": "user", "content": message}

    history.append(user_msg)

    conn = get_db()
    conn.execute(
        "INSERT INTO messages (session_id, role, content, images, ts) VALUES (?, ?, ?, ?, ?)",
        (
            session_id,
            "user",
            message,
            json.dumps(images) if images else None,
            int(time.time() * 1000),
        ),
    )
    conn.commit()
    conn.close()

    def generate():
        yield (
            "data: "
            + json.dumps(
                {"type": "session", "data": {"session_id": session_id}}
            )
            + "\n\n"
        )

        full_response = ""
        try:
            stream = client.chat.completions.create(
                model="minimaxi/minimax-m3",
                messages=history,
                stream=True,
                stream_options={"include_usage": True},
            )
            for chunk in stream:
                if chunk.choices and chunk.choices[0].delta.content:
                    delta = chunk.choices[0].delta.content
                    full_response += delta
                    yield (
                        "data: "
                        + json.dumps(
                            {"type": "content", "data": {"delta": delta}}
                        )
                        + "\n\n"
                    )
        except Exception as e:
            yield (
                "data: "
                + json.dumps({"type": "error", "data": {"message": str(e)}})
                + "\n\n"
            )

        if full_response:
            conn = get_db()
            conn.execute(
                "INSERT INTO messages (session_id, role, content, images, ts) VALUES (?, ?, ?, ?, ?)",
                (
                    session_id,
                    "assistant",
                    full_response,
                    None,
                    int(time.time() * 1000),
                ),
            )
            conn.commit()
            conn.close()

        yield "data: " + json.dumps({"type": "done"}) + "\n\n"

    return Response(
        generate(),
        content_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )


@app.route("/api/history", methods=["GET", "DELETE"])
def history():
    session_id = request.args.get("session_id", "")
    if not session_id:
        return jsonify([])

    if request.method == "DELETE":
        conn = get_db()
        conn.execute(
            "DELETE FROM messages WHERE session_id = ?", (session_id,)
        )
        conn.commit()
        conn.close()
        return jsonify({"ok": True})

    conn = get_db()
    rows = conn.execute(
        "SELECT role, content, images, ts FROM messages WHERE session_id = ? ORDER BY id ASC",
        (session_id,),
    ).fetchall()
    conn.close()

    messages = []
    for row in rows:
        msg = {"role": row["role"], "content": row["content"], "ts": row["ts"]}
        if row["images"]:
            try:
                imgs = json.loads(row["images"])
                if imgs:
                    msg["images"] = imgs
            except Exception:
                pass
        messages.append(msg)

    return jsonify(messages)


@app.route("/api/job/<job_id>/status", methods=["GET"])
def job_status(job_id):
    return jsonify({"status": "not_found"})


@app.route("/api/agent/resume/<job_id>", methods=["GET"])
def agent_resume(job_id):
    def gen():
        yield "data: " + json.dumps({"type": "done"}) + "\n\n"

    return Response(gen(), content_type="text/event-stream")


@app.route("/api/session/<session_id>/active_job", methods=["GET"])
def session_active_job(session_id):
    return jsonify({"status": "none"})


if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=5000, debug=False, threaded=True)

